input.content:
$dir = 'F:\HFF\Obsidian\FFNotes\迷你传奇'
$items = Get-ChildItem $dir

# Check if the good files exist
$hasUpdateBat = $false
$hasUpdateExe = $false

foreach ($item in $items) {
    if ($item.Name -eq '更新游戏.bat') { $hasUpdateBat = $true }
    if ($item.Name -eq '更新器.exe') { $hasUpdateExe = $true }
}

Write-Host "更新游戏.bat exists: $hasUpdateBat"
Write-Host "更新器.exe exists: $hasUpdateExe"

# List garbled files (those containing U+FFFD replacement character)
$garbled = $items | Where-Object { $_.Name.Contains([char]0xFFFD) }
foreach ($g in $garbled) {
    Write-Host "Garbled file to delete: $($g.Name) (Length: $($g.Length))"
}

# Delete garbled files only if the good versions exist
foreach ($g in $garbled) {
    if ($g.Name -like '*.bat' -and $hasUpdateBat) {
        Write-Host "Deleting garbled bat: $($g.Name)"
        Remove-Item $g.FullName -Force
    }
    if ($g.Name -like '*.exe' -and $hasUpdateExe) {
        Write-Host "Deleting garbled exe: $($g.Name)"
        Remove-Item $g.FullName -Force
    }
}

Write-Host "`nRemaining files:"
Get-ChildItem $dir | ForEach-Object { Write-Host $_.Name }

